import {escapeHtml as esc} from './components.js';
import {fetchResearch,eventMarkup,pct,coverageMarkup,updated,showEventHistory} from './research-view.js';
import {sectorMovers,sectorDate,sectorEventDate,sectorContributions} from './research-model.js';
import {openPdfViewer} from './pdf-viewer.js';
import {readWatchlist,toggleWatchlist} from './watchlist.js';
export function monthlyRelatedEvents(items){const seen=new Set();return items.filter(e=>['earnings','calendar','report'].includes(e.kind)).sort((a,b)=>String(b.collectedAt||b.updatedAt||'').localeCompare(String(a.collectedAt||a.updatedAt||''))).filter(e=>{const key=e.kind==='calendar'?JSON.stringify([e.source,e.title,e.at||e.date]):e.eventId||e.id;if(seen.has(key))return false;seen.add(key);return true;}).sort((a,b)=>b.date.localeCompare(a.date));}
export function mountSectorResearch(root,{navigate,beforeNavigate}){
 let selection=null,request=null,version=0,identity=null,data=null,viewer,eventDate=null,dateBasis=null,dateChosen=false;const life=new AbortController();
 function render(){if(!selection){root.hidden=true;root.replaceChildren();return;}root.hidden=false;const {sector,market,feed}=selection,stocks=sectorMovers(sector.stocks||[]),keys=new Set(stocks.map(s=>s.market+':'+s.id)),contributions=feed?.analysis==='monthly'?null:sectorContributions(stocks),monthly=feed?.analysis==='monthly',rawEvents=(data?.items||[]).filter(e=>keys.has(e.key)&&(monthly?sectorEventDate(e)>=feed.month+'-01'&&sectorEventDate(e)<=feed.baseDate:sectorEventDate(e)===eventDate)),events=monthly?monthlyRelatedEvents(rawEvents):rawEvents;
  root.innerHTML=`<div class="research-heading"><div><h3>${esc(sector.name)}</h3><p>${monthly?'월 누적 상승·하락 종목':contributions?'섹터 등락 기여도':'상승·하락 종목'} · ${market==='US'?'미국':'국내'}</p></div><button data-sector-panel-close aria-label="섹터 상세 닫기">×</button></div><p class="research-note">${esc(feed?.source||'연결된 시세')} · ${feed?.asOfKind==='received'?'조회 ':''}${esc(updated(feed?.asOf))}</p>${monthly?`<div class="monthly-sector-summary"><p>${esc(feed.startDate)} → ${esc(feed.baseDate)} · 중간값 ${pct(sector.median)}</p><p>상승 ${sector.up} · 보합 ${sector.flat} · 하락 ${sector.down} · ${sector.used}개</p><p>가장 강함: ${esc(stocks[0]?.name||'—')} ${pct(stocks[0]?.changePct)}</p><p>가장 약함: ${esc(stocks.at(-1)?.name||'—')} ${pct(stocks.at(-1)?.changePct)}</p><p>지수 초과: ${Number.isFinite(feed.benchmark?.changePct)?stocks.filter(s=>s.excessPct>0).length+'개':'비교 지수 연결 필요'}</p></div>`:''}<div class="sector-detail-stocks">${stocks.map(s=>`<div class="sector-stock-with-actions"><button data-sector-research-stock="${esc(s.market+':'+s.id)}"><span><b>${esc(s.ticker)}</b><small>${esc(s.name)}</small><small>${s.asOfKind==='received'?'조회 ':'시세 기준 '}${esc(updated(s.asOf))}</small></span><strong class="${s.changePct>0?'up':s.changePct<0?'negative':''}">${pct(s.quoteAvailable===false?null:s.changePct)}${monthly&&s.excessPct>0?'<small>지수 초과 +'+s.excessPct.toFixed(2)+'%p</small>':''}${contributions?'<small>기여 '+contributions.get(s.market+':'+s.id).toFixed(3)+'%p</small>':''}</strong></button><div class="sector-stock-actions"><button data-sector-watch="${esc(s.market+':'+s.id)}" aria-pressed="${readWatchlist().includes(s.market+':'+s.id)}" aria-label="${esc(s.name)} 관심종목">${readWatchlist().includes(s.market+':'+s.id)?'★ 관심':'☆ 관심'}</button><button data-sector-compare="${esc(s.market+':'+s.id)}" aria-label="${esc(s.name)} 비교 추가">비교 추가</button></div></div>`).join('')}</div><p class="sector-action-status" role="status"></p><p class="research-note">유효 시세 ${stocks.filter(s=>s.quoteAvailable!==false&&Number.isFinite(s.changePct)).length} / 구성종목 ${stocks.length}개 · 결측 종목은 0%로 계산하지 않습니다.</p><div class="sector-event-date" ${monthly?'hidden':''}><label>관련 이벤트 날짜 <input type="date" value="${eventDate}" data-sector-event-date></label><small>${dateBasis?.confirmed&&eventDate===dateBasis.date?"시세 기준일과 같은 날짜":"선택한 원본 날짜의 이벤트"} · ${market==="US"?"미국 현지 날짜":"한국 날짜"} 기준${dateBasis?.confirmed?"":" · 시세 기준일 미제공"}</small></div><h4>${monthly?esc(feed.month)+' 같은 기간 일정·리포트':'관련 일정·리포트'}</h4><div class="sector-related-events">${data?events.length?events.map(e=>eventMarkup(e,{stock:e.kind!=='calendar'})).join(''):'<p class="research-empty">선택 기간에 확인된 관련 이벤트가 없습니다.</p>':'<p role="status">관련 자료 확인 중…</p>'}</div><div class="research-coverage">${coverageMarkup(data?.coverage)}</div><p class="research-note">${monthly?'종목별 월 누적 수익률입니다. 같은 기간의 자료이며 가격 변동의 원인으로 단정하지 않습니다.':contributions?'동일 기준일 전일 시가총액 비중 × 당일 등락률입니다. 공식 섹터지수가 아닙니다.':'전일 시가총액·수익률 기준일이 확인되지 않아 기여도를 계산하지 않습니다.'} 같은 날의 이벤트를 주가 변동 원인으로 단정하지 않습니다.</p>`;
 }
 async function select(next,keepDate=false){const same=selection&&next&&selection.market===next.market&&selection.sector.id===next.sector.id;if(same&&dateChosen)keepDate=true;if(!same)dateChosen=false;selection=next;if(!next){++version;request?.abort();identity=null;data=null;render();return;}if(!keepDate){dateBasis=sectorDate(next.feed,next.market);eventDate=dateBasis.date;}const keys=[...new Set(next.sector.stocks.map(s=>s.market+':'+s.id))].sort(),key=next.market+'|'+next.sector.id+'|'+(next.feed?.analysis==='monthly'?next.feed.month+'|'+next.feed.baseDate:eventDate)+'|'+keys.join(',');render();if(key===identity)return;identity=key;request?.abort();request=new AbortController();const n=++version;data=null;render();try{const result=await fetchResearch(keys,request.signal,next.feed?.analysis==='monthly'?{from:next.feed.month+'-01',to:next.feed.baseDate}:{date:eventDate});if(n!==version||!selection)return;data=result;render();}catch{if(n===version&&selection){data={items:[],coverage:{earnings:{status:'error',message:'관련 자료 연결 확인 필요'}}};render();}}}
 root.addEventListener('change',e=>{if(e.target.matches('[data-sector-event-date]')&&e.target.value){eventDate=e.target.value;dateChosen=true;select(selection,true);}},{signal:life.signal});
 root.addEventListener('click',e=>{const action=e.target.closest('[data-sector-watch],[data-sector-compare]');if(action){const key=action.dataset.sectorWatch||action.dataset.sectorCompare,stock=selection?.sector.stocks.find(s=>s.market+':'+s.id===key);if(!stock)return;const status=root.querySelector('.sector-action-status');try{if(action.hasAttribute('data-sector-watch')){const saved=toggleWatchlist(stock.market,stock.id);action.setAttribute('aria-pressed',String(saved));action.textContent=saved?'★ 관심':'☆ 관심';status.textContent=stock.name+' · 관심종목 '+(saved?'추가':'해제');}else dispatchEvent(new CustomEvent('moa-compare-add',{detail:{market:stock.market,ticker:stock.id,name:stock.name}}));}catch(error){status.textContent=error.message||'저장 실패 · 다시 시도해 주세요.';}return;}showEventHistory(e,life.signal);const b=e.target.closest('[data-sector-research-stock]');if(b){beforeNavigate?.();navigate('/stock/'+b.dataset.sectorResearchStock.replace(':','/')+(selection?.feed?.analysis==='monthly'?'?chartDate='+selection.feed.baseDate:''));}if(e.target.closest('[data-sector-panel-close]')){select(null);root.dispatchEvent(new CustomEvent('sector-detail-close',{bubbles:true}));}const r=e.target.closest('[data-research-report]');if(r){const report=data?.reports?.find(p=>p.id===r.dataset.researchReport);if(report?.attachment?.url){viewer?.close();viewer=openPdfViewer({...report,fields:{title:{value:report.title}}});}}const chart=e.target.closest('[data-research-date]');if(chart){const ev=data?.items?.find(i=>i.chartDate===chart.dataset.researchDate&&i.eventId===chart.closest('[data-event-id]')?.dataset.eventId);if(ev){beforeNavigate?.();navigate('/stock/'+ev.key.replace(':','/')+'?chartDate='+ev.chartDate);}}if(e.target.closest('a[data-nav]'))beforeNavigate?.();},{signal:life.signal});
 const syncFavorites=()=>{const saved=readWatchlist();for(const b of root.querySelectorAll('[data-sector-watch]')){const yes=saved.includes(b.dataset.sectorWatch);b.setAttribute('aria-pressed',String(yes));b.textContent=yes?'★ 관심':'☆ 관심';}};addEventListener('moa-watchlist',syncFavorites,{signal:life.signal});addEventListener('storage',syncFavorites,{signal:life.signal});
 return {select,destroy(){++version;selection=null;identity=null;data=null;life.abort();request?.abort();viewer?.close();}};
}
